from pathlib import Path
emails=[('launch','Your conference room has a game mode.','THE LAUNCH','Clock out of ordinary.','One screen. A few phones. Six ways to make a scene. Ruckus turns the room you already have into the party you didn’t know you needed.','Open a room','Start with Room Temperature. Read the room before you try to beat it.'),('friday','Friday needs an outro.','THE FRIDAY FINISH','Close the tabs.<br>Open the room.','The week has earned a ten-minute detour. Choose a mix, scan your people in, and find out who’s been quietly preparing to win.','Make a little Ruckus','Good mix: Room Temperature → Hotwire → Sellout.'),('new-game','Art skills strictly optional.','GAME DROP / SCRIBBLE SHIFT','The art department<br>is now everyone.','One finger. Six colors. A coffee machine on vacation. Scribble Shift turns your phone into a canvas and your coworkers into very opinionated art critics.','Meet Scribble Shift','Draw. Send. Vote. Talent has absolutely no bearing on participation.'),('party','One room. Six ways to make a scene.','THE OFFICE PARTY','Your agenda just<br>got a plot twist.','The offsite needs a better break. Put the room on a screen and give everyone a controller they already own. Twenty alter egos. Zero name tags.','Build your lineup','Add pitches and captions for a room that creates its own entertainment.'),('remote','Miles apart. Same loud room.','REMOTE PLAY','Different desks.<br>Same wavelength.','Share your host screen on the call. Everyone joins on a phone or separate browser tab. Keep the microphones open for the bits between rounds.','Open a remote room','Remote play requires the publicly hosted Node service. Same-Wi-Fi LAN play works locally.')]
for slug,subject,tag,title,body,cta,note in emails:
 html=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{subject}</title></head><body style="margin:0;background:#eae9df;font-family:Arial,sans-serif;color:#191a24"><div style="display:none;max-height:0;overflow:hidden">{subject} Your phone is the controller.</div><table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr><td align="center" style="padding:30px 15px"><table role="presentation" width="600" cellpadding="0" cellspacing="0" style="width:100%;max-width:600px;background:#f9f7ed;border:1px solid #191a24"><tr><td style="padding:28px 30px;font-size:36px;font-weight:900;letter-spacing:-2px">ruckus<span style="color:#2548f4">*</span></td></tr><tr><td style="padding:40px 30px;background:#2548f4;color:#f9f7ed"><p style="font-size:10px;letter-spacing:2px;color:#f6ed51;font-weight:bold;margin:0 0 25px">{tag}</p><h1 style="font-size:44px;line-height:1.04;letter-spacing:-2px;margin:0 0 28px">{title}</h1><p style="font-size:16px;line-height:1.65;margin:0 0 30px;color:#e2e6ff">{body}</p><a href="/host" style="display:inline-block;padding:17px 24px;background:#f6ed51;color:#191a24;border-radius:6px;text-decoration:none;font-weight:bold;font-size:14px">{cta} ↗</a></td></tr><tr><td style="padding:32px 30px"><h2 style="font-size:21px;letter-spacing:-.5px;margin:0 0 15px">Good company. Questionable competition.</h2><p style="font-size:14px;line-height:1.65;color:#5a5865">{note}</p><p style="font-size:11px;margin-top:30px;padding-top:22px;border-top:1px solid #d9d8cf;line-height:1.6;color:#6b6974">Self-initiated concept by Anthony Volatile / Volatile Solutions.<br>Campaign preview only. No emails sent. Replace relative links with your hosted origin before any real use.</p></td></tr></table></td></tr></table></body></html>'''
 Path(f'public/campaign/email-{slug}.html').write_text(html)
